-- MVP pracovního trhu. Vygenerováno na základě CSV.
BEGIN;
SET LOCAL client_encoding = 'UTF8';
SET LOCAL standard_conforming_strings = on;

CREATE TABLE IF NOT EXISTS public."DOJEZDOVE_DOBY" (
    kod_zsj integer NOT NULL REFERENCES public."ZSJ" (kod),
    redizo text NOT NULL REFERENCES public."STREDNI_SKOLY" (redizo),
    slot_prijezdu text NOT NULL,
    doba_jizdy real,
    PRIMARY KEY (kod_zsj, redizo, slot_prijezdu)
);
CREATE INDEX IF NOT EXISTS dojezdove_doby_redizo_idx ON public."DOJEZDOVE_DOBY" (redizo);
CREATE TEMP TABLE import_dojezdove_doby (kod_zsj integer, redizo text, slot_prijezdu text, doba_jizdy real,
    PRIMARY KEY (kod_zsj, redizo, slot_prijezdu)) ON COMMIT DROP;


DELETE FROM public."DOJEZDOVE_DOBY";
DO $$ BEGIN IF NOT ((SELECT COUNT(*) FROM public."DOJEZDOVE_DOBY") = 28526) THEN RAISE EXCEPTION 'Nesouhlasí počet záznamů'; END IF; END $$;

COMMIT;
